const api=require('./miniprogram/utils/api');
const pending=[]; api.request=()=>new Promise(resolve=>pending.push(resolve));
const p=require('./miniprogram/controllers').create('resource');
p.setData=function(v){ for(const [k,x] of Object.entries(v)){const parts=k.split('.');let d=this.data;for(const y of parts.slice(0,-1)) d=d[y]||(d[y]={});d[parts.at(-1)]=x;}};
p.setData({id:1,item:{schedule:[]},scheduleHasMore:true});
const old=p.loadSchedule(2);
const fresh=p.load();
pending[1]({schedule:[],schedule_page:1,schedule_total:31,schedule_has_more:true,policy:{window_days:14}});
fresh.then(()=>{pending[0]({schedule:[],schedule_page:2,schedule_total:31,schedule_has_more:false});return old;}).then(()=>console.log(JSON.stringify({loading:p.data.loading,scheduleBusy:p.data.scheduleBusy,scheduleHasMore:p.data.scheduleHasMore,canRequestNext:!p.data.scheduleBusy&&!p.data.loading})));
